/// document-relations: Add, read both ways, remove
private struct DocumentRelationsExample0: View {
    @State private var relations = [
        MonarchDocumentRelation(
            id: "r1",
            type: "parent-of",
            direction: .outgoing,
            target: MonarchDocumentRelationTarget(id: "d1", title: "Hiring plan", description: "People")
        ),
        MonarchDocumentRelation(
            id: "r2",
            type: "parent-of",
            direction: .incoming,
            target: MonarchDocumentRelationTarget(id: "d2", title: "Company handbook", description: "Workspace root")
        ),
        MonarchDocumentRelation(
            id: "r3",
            type: "supersedes",
            direction: .outgoing,
            target: MonarchDocumentRelationTarget(id: "d3", title: "Travel policy (2025)", description: "Operations")
        ),
    ]
    private let library = [
        MonarchDocumentRelationTarget(id: "d1", title: "Hiring plan", description: "People"),
        MonarchDocumentRelationTarget(id: "d2", title: "Company handbook", description: "Workspace root"),
        MonarchDocumentRelationTarget(id: "d3", title: "Travel policy (2025)", description: "Operations"),
        MonarchDocumentRelationTarget(id: "d4", title: "Budget 2027", description: "Finance"),
        MonarchDocumentRelationTarget(id: "d5", title: "Brand guidelines", description: "Marketing"),
        MonarchDocumentRelationTarget(id: "d6", title: "Security checklist", description: "Engineering"),
    ]

    var body: some View {
        MonarchDocumentRelations(
            relations,
            candidates: library,
            onOpen: { _ in },
            onAdd: { targetID, type in
                if let target = library.first(where: { $0.id == targetID }) {
                    relations.append(MonarchDocumentRelation(id: "r\(relations.count + 1)", type: type, target: target))
                }
            },
            onRemove: { relationID in relations.removeAll { $0.id == relationID } }
        )
    }
}

